/** Pure operations on the explorer's graph model: merging query results, removing nodes, neighbourhoods and paths. */
import { seedNodePositions } from "./graph-geometry.ts";
import { bindingsToTriples, compactTerm, predicateLabel, termKind, tripleEdgeId } from "./graph-terms.ts";
import type { Graph, GraphNode, PointerPosition } from "./graph-types.ts";
import { mergeNodeTypes } from "./metadata-lookup.ts";
import { sparqlNodeId, type SparqlTerm } from "./rdf-terms.ts";

export function leafClusterForNode(graph: Graph, nodeId: string) {
  const neighbors = new Map<string, Set<string>>();
  graph.edges.forEach((edge) => {
    if (edge.source === edge.target) return;
    const source = neighbors.get(edge.source);
    if (source) source.add(edge.target);
    else neighbors.set(edge.source, new Set([edge.target]));
    const target = neighbors.get(edge.target);
    if (target) target.add(edge.source);
    else neighbors.set(edge.target, new Set([edge.source]));
  });

  const cluster = new Set([nodeId]);
  (neighbors.get(nodeId) ?? []).forEach((neighborId) => {
    const neighborConnections = neighbors.get(neighborId);
    if (
      neighborConnections?.size === 1 &&
      neighborConnections.has(nodeId)
    ) {
      cluster.add(neighborId);
    }
  });
  return cluster;
}

export function directNeighborIds(graph: Graph, nodeIds: Set<string>) {
  const neighbors = new Set<string>();
  graph.edges.forEach((edge) => {
    if (nodeIds.has(edge.source) && !nodeIds.has(edge.target)) {
      neighbors.add(edge.target);
    }
    if (nodeIds.has(edge.target) && !nodeIds.has(edge.source)) {
      neighbors.add(edge.source);
    }
  });
  return neighbors;
}

export function seedIncrementalNodes(
  graph: Graph,
  previousNodeIds: Set<string>,
  anchorIds: string[],
) {
  const newNodes = graph.nodes.filter((node) => !previousNodeIds.has(node.id));
  const usableAnchorIds = [...new Set(anchorIds)].filter((anchorId) => {
    const anchor = graph.nodes.find((node) => node.id === anchorId);
    return anchor?.x !== undefined && anchor.y !== undefined;
  });
  if (!usableAnchorIds.length || !newNodes.length) {
    return graph;
  }
  const nodeById = new Map(graph.nodes.map((node) => [node.id, node]));
  const newNodeIds = new Set(newNodes.map((node) => node.id));
  const anchorGroups = new Map(
    usableAnchorIds.map((anchorId) => [anchorId, [] as GraphNode[]]),
  );
  newNodes.forEach((node) => {
    const connectedAnchors = usableAnchorIds.filter((anchorId) =>
      graph.edges.some(
        (edge) =>
          (edge.source === anchorId && edge.target === node.id) ||
          (edge.target === anchorId && edge.source === node.id),
      ),
    );
    const anchorId = (connectedAnchors.length ? connectedAnchors : usableAnchorIds)
      .slice()
      .sort(
        (left, right) =>
          (anchorGroups.get(left)?.length ?? 0) -
            (anchorGroups.get(right)?.length ?? 0) ||
          left.localeCompare(right),
      )[0];
    anchorGroups.get(anchorId)?.push(node);
  });

  const seededById = new Map<string, PointerPosition>();
  anchorGroups.forEach((group, anchorId) => {
    const anchor = nodeById.get(anchorId);
    if (
      !anchor ||
      anchor.x === undefined ||
      anchor.y === undefined ||
      !group.length
    ) {
      return;
    }
    const existingNeighborAngles = graph.edges
      .flatMap((edge) => {
        const neighborId =
          edge.source === anchorId
            ? edge.target
            : edge.target === anchorId
              ? edge.source
              : null;
        if (
          !neighborId ||
          newNodeIds.has(neighborId) ||
          !previousNodeIds.has(neighborId)
        ) {
          return [];
        }
        const neighbor = nodeById.get(neighborId);
        if (neighbor?.x === undefined || neighbor.y === undefined) return [];
        return [Math.atan2(neighbor.y - anchor.y!, neighbor.x - anchor.x!)];
      })
      .sort((left, right) => left - right);

    let gapStart = -Math.PI;
    let gapSize = Math.PI * 2;
    if (existingNeighborAngles.length) {
      gapSize = -1;
      existingNeighborAngles.forEach((angle, index) => {
        const next =
          index === existingNeighborAngles.length - 1
            ? existingNeighborAngles[0] + Math.PI * 2
            : existingNeighborAngles[index + 1];
        if (next - angle > gapSize) {
          gapStart = angle;
          gapSize = next - angle;
        }
      });
    }
    const gapCenter = gapStart + gapSize / 2;
    const perRing = 8;
    group.forEach((node, index) => {
      const ring = Math.floor(index / perRing);
      const indexInRing = index % perRing;
      const countInRing = Math.min(perRing, group.length - ring * perRing);
      const usableArc = Math.min(
        Math.PI * 1.7,
        Math.max(0.86, gapSize - 0.36),
      );
      const progress =
        countInRing === 1 ? 0.5 : indexInRing / (countInRing - 1);
      const angle = gapCenter - usableArc / 2 + progress * usableArc;
      const radius = 190 + ring * 126;
      seededById.set(node.id, {
        x: anchor.x! + Math.cos(angle) * radius,
        y: anchor.y! + Math.sin(angle) * radius,
      });
    });
  });

  return {
    ...graph,
    nodes: graph.nodes.map((node) => ({
      ...node,
      ...seededById.get(node.id),
    })),
  };
}

export function mergeTriples(
  graph: Graph,
  triples: ReturnType<typeof bindingsToTriples>,
  replace = false,
  batchId?: string,
): Graph {
  const baseNodes: GraphNode[] = replace
    ? []
    : graph.nodes.map((node) => ({
        ...node,
        types: node.types?.map((type) => ({ ...type })),
      }));
  const baseEdges = replace ? [] : graph.edges;
  const nodeById = new Map(baseNodes.map((node) => [node.id, node]));
  const edgeIds = new Set(
    baseEdges.flatMap((edge) => [
      edge.id,
      tripleEdgeId(edge.source, edge.predicate, edge.target),
    ]),
  );
  const nodes = [...baseNodes];
  const edges = baseEdges.map((edge) => ({ ...edge }));
  const edgeById = new Map(edges.map((edge) => [edge.id, edge]));
  edges.forEach((edge) => {
    edgeById.set(tripleEdgeId(edge.source, edge.predicate, edge.target), edge);
  });

  for (const triple of triples) {
    const source = nodeById.get(triple.source);
    if (!source) {
      const next = {
        id: triple.source,
        termValue: triple.sourceValue,
        label: triple.sourceLabel,
        labelInput: triple.sourceLabelInput,
        kind: triple.sourceKind,
        datatype: triple.sourceDatatype,
        language: triple.sourceLanguage,
        direction: triple.sourceDirection,
        x: 180 + (nodes.length % 4) * 180,
        y: 170 + Math.floor(nodes.length / 4) * 120,
      } satisfies GraphNode;
      nodeById.set(next.id, next);
      nodes.push(next);
    } else if (
      source.label === compactTerm(source.termValue ?? source.id) &&
      triple.sourceLabel !== source.label
    ) {
      source.label = triple.sourceLabel;
      source.labelInput = triple.sourceLabelInput;
    }

    const target = nodeById.get(triple.target);
    if (!target) {
      const next = {
        id: triple.target,
        termValue: triple.targetValue,
        label: triple.targetLabel,
        labelInput: triple.targetLabelInput,
        kind: triple.targetKind,
        datatype: triple.targetDatatype,
        language: triple.targetLanguage,
        direction: triple.targetDirection,
        x: 180 + (nodes.length % 4) * 180,
        y: 170 + Math.floor(nodes.length / 4) * 120,
      } satisfies GraphNode;
      nodeById.set(next.id, next);
      nodes.push(next);
    } else if (
      target.label === compactTerm(target.termValue ?? target.id) &&
      triple.targetLabel !== target.label
    ) {
      target.label = triple.targetLabel;
      target.labelInput = triple.targetLabelInput;
    }

    const id = tripleEdgeId(triple.source, triple.predicate, triple.target);
    if (!edgeIds.has(id)) {
      edgeIds.add(id);
      const next = {
        id,
        source: triple.source,
        predicate: triple.predicate,
        label: triple.predicateLabel,
        labelInput: triple.predicateLabelInput,
        target: triple.target,
        batchId,
      };
      edges.push(next);
      edgeById.set(id, next);
    } else {
      const edge = edgeById.get(id);
      if (edge && edge.label === predicateLabel(edge.predicate)) {
        edge.label = triple.predicateLabel;
        edge.labelInput = triple.predicateLabelInput;
      }
    }
  }

  const merged: Graph = {
    nodes: replace ? seedNodePositions(nodes) : nodes,
    edges,
    revision: graph.revision + 1,
    ...(!replace && graph.statementLinks ? { statementLinks: graph.statementLinks } : {}),
  };
  return replace ? preserveSharedNodePositions(merged, graph) : merged;
}

/**
 * Resources added as cards of their own, without any statement (the Types page adds a class this way, not its
 * instances). Values are no resources; cards already in the graph stay as they are, and nothing new is the same graph.
 */
export function mergeResourceNodes(graph: Graph, terms: readonly SparqlTerm[]): Graph {
  const nodeIds = new Set(graph.nodes.map((node) => node.id));
  const added: GraphNode[] = [];
  for (const term of terms) {
    if (term.type === "literal") continue;
    const id = sparqlNodeId(term);
    if (nodeIds.has(id)) continue;
    nodeIds.add(id);
    const index = graph.nodes.length + added.length;
    added.push({
      id,
      termValue: term.value,
      label: compactTerm(term.value),
      labelInput: null,
      kind: termKind(term),
      x: 180 + (index % 4) * 180,
      y: 170 + Math.floor(index / 4) * 120,
    });
  }
  return added.length ? { ...graph, nodes: [...graph.nodes, ...added], revision: graph.revision + 1 } : graph;
}

/** The edges of `after` that `before` does not hold, in `after`'s order: one pass over each graph, however large. */
export function newEdgesOf(before: Pick<Graph, "edges">, after: Pick<Graph, "edges">) {
  const existing = new Set(before.edges.map((edge) => edge.id));
  return after.edges.filter((edge) => !existing.has(edge.id));
}

export function cloneGraph(graph: Graph): Graph {
  return {
    revision: graph.revision,
    nodes: graph.nodes.map((node) => ({
      ...node,
      types: node.types?.map((type) => ({ ...type })),
    })),
    edges: graph.edges.map((edge) => ({ ...edge })),
    ...(graph.statementLinks ? { statementLinks: graph.statementLinks.map((link) => ({ ...link })) } : {}),
  };
}

export function preserveSharedNodePositions(next: Graph, current: Graph): Graph {
  const currentPositions = new Map(
    current.nodes.flatMap((node) =>
      node.x !== undefined && node.y !== undefined
        ? [[node.id, { x: node.x, y: node.y }] as const]
        : [],
    ),
  );
  return {
    ...next,
    nodes: next.nodes.map((node) => ({
      ...node,
      ...currentPositions.get(node.id),
    })),
  };
}

const RDF_TYPE_PREDICATE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";

export function removeGraphNodes(graph: Graph, nodeIds: Set<string>): Graph {
  const edges = graph.edges.filter(
    (edge) => !nodeIds.has(edge.source) && !nodeIds.has(edge.target),
  );
  // A literal value belongs to the resources that state it; once none is left, it goes too. So does a class that was
  // only there as the type of removed resources: the canvas leaves a class out while rdf:type links reach it, and would
  // otherwise draw it on its own once they are gone.
  const referenced = new Set(edges.flatMap((edge) => [edge.source, edge.target]));
  const typeOfRemoved = new Set(
    graph.edges.flatMap((edge) => (edge.predicate === RDF_TYPE_PREDICATE && nodeIds.has(edge.source) ? [edge.target] : [])),
  );
  return {
    nodes: graph.nodes.filter(
      (node) =>
        !nodeIds.has(node.id) &&
        (node.kind !== "literal" || referenced.has(node.id)) &&
        (!typeOfRemoved.has(node.id) || referenced.has(node.id)),
    ),
    edges,
    revision: graph.revision + 1,
    ...(graph.statementLinks ? { statementLinks: graph.statementLinks.filter((link) => !nodeIds.has(link.source)) } : {}),
  };
}

export function shortestPathInGraph(graph: Graph, starts: string[], goal: string) {
  const startSet = new Set(starts);
  if (startSet.has(goal)) return { nodeIds: new Set([goal]), edgeIds: new Set<string>() };
  const adjacency = new Map<string, Array<{ nodeId: string; edgeId: string }>>();
  graph.edges.forEach((edge) => {
    const outgoing = adjacency.get(edge.source) ?? [];
    outgoing.push({ nodeId: edge.target, edgeId: edge.id });
    adjacency.set(edge.source, outgoing);
    const incoming = adjacency.get(edge.target) ?? [];
    incoming.push({ nodeId: edge.source, edgeId: edge.id });
    adjacency.set(edge.target, incoming);
  });
  const queue = [...startSet];
  const parent = new Map<string, { nodeId: string; edgeId: string }>();
  const seen = new Set(queue);
  for (let cursor = 0; cursor < queue.length; cursor += 1) {
    const nodeId = queue[cursor];
    for (const neighbor of adjacency.get(nodeId) ?? []) {
      if (seen.has(neighbor.nodeId)) continue;
      seen.add(neighbor.nodeId);
      parent.set(neighbor.nodeId, { nodeId, edgeId: neighbor.edgeId });
      if (neighbor.nodeId === goal) {
        const nodeIds = new Set<string>([goal]);
        const edgeIds = new Set<string>();
        let current = goal;
        while (!startSet.has(current)) {
          const step = parent.get(current);
          if (!step) break;
          nodeIds.add(step.nodeId);
          edgeIds.add(step.edgeId);
          current = step.nodeId;
        }
        return { nodeIds, edgeIds };
      }
      queue.push(neighbor.nodeId);
    }
  }
  return null;
}

export function commonNeighborIds(graph: Graph, nodeIds: string[]) {
  if (nodeIds.length < 2) return new Set<string>();
  const neighbors = nodeIds.map((nodeId) => {
    const values = new Set<string>();
    graph.edges.forEach((edge) => {
      if (edge.source === nodeId) values.add(edge.target);
      if (edge.target === nodeId) values.add(edge.source);
    });
    return values;
  });
  return new Set(
    [...neighbors[0]].filter((candidate) =>
      neighbors.slice(1).every((values) => values.has(candidate)),
    ),
  );
}

/**
 * Gives resources the types their loaded rdf:type statements state, so a large graph is coloured by type at once
 * instead of waiting for type queries (which only cover the first nodes). Types already known are kept; a node a
 * lookup has answered for keeps them as the lookup does (mergeNodeTypes: ordered, at most NODE_TYPE_LIMIT). The graph
 * is returned unchanged when nothing is new.
 */
export function withLoadedTypes(graph: Graph): Graph {
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const stated = new Map<string, string[]>();
  for (const edge of graph.edges) {
    // Types are IRIs, as the type lookup asks for: a blank-node class (an anonymous OWL class) has no name to show.
    if (edge.predicate !== RDF_TYPE_PREDICATE || byId.get(edge.target)?.kind !== "iri") continue;
    const list = stated.get(edge.source);
    if (list) list.push(edge.target);
    else stated.set(edge.source, [edge.target]);
  }
  if (!stated.size) return graph;
  let changed = false;
  const nodes = graph.nodes.map((node) => {
    const typeIds = stated.get(node.id);
    if (!typeIds || node.kind === "literal") return node;
    const knownIds = new Set((node.types ?? []).map((type) => type.id));
    const added = [...new Set(typeIds)].filter((id) => !knownIds.has(id));
    if (!added.length && node.types) return node;
    const loaded = added.map((id) => ({ id, label: byId.get(id)?.label ?? compactTerm(id),
      ...(byId.get(id)?.labelInput !== undefined ? { labelInput: byId.get(id)!.labelInput } : {}) }));
    const known = node.types ?? [];
    const types = node.typesLookedUp ? mergeNodeTypes(known, loaded) : [...known, ...loaded];
    // Types the cap leaves out stay out: nothing new.
    if (types.length === known.length && types.every((type, index) => type === known[index])) return node;
    changed = true;
    return { ...node, types };
  });
  return changed ? { ...graph, nodes } : graph;
}
